//http://codeforces.com/problemset/problem/78/E
//Evacuation

#include <bits/stdc++.h>

using namespace std;

const int MAX_LEN = 300;

enum CellStatus { CLEAR = -1, REACTION_POINT = -2, DANGER_ZONE = -3, SHELTER = CLEAR };

struct Arc {
    int origin, terminus, reverse, current, limit;
    Arc() : origin(0), terminus(0), reverse(0), current(0), limit(0) {}
    Arc(int o, int t, int r, int c, int l) : origin(o), terminus(t), reverse(r), current(c), limit(l) {}
    int available() const { return limit - current; }
};

class FlowEngine {
public:
    int vertexCount;
    vector<Arc*>* adjacency;
    Arc** parentArc;
    vector<int> level;

    FlowEngine(int n) : vertexCount(n), adjacency(new vector<Arc*>[n]), parentArc(new Arc*[n]), level(n, -1) {}

    ~FlowEngine() {
        for (int i = 0; i < vertexCount; ++i) {
            for (auto* e : adjacency[i]) delete e;
            adjacency[i].clear();
        }
        delete[] adjacency;
        delete[] parentArc;
    }

    void addArc(int u, int v, int cap) {
        Arc* forward = new Arc(u, v, (int)adjacency[v].size(), 0, cap);
        Arc* backward = new Arc(v, u, (int)adjacency[u].size(), 0, 0);
        adjacency[u].push_back(forward);
        adjacency[v].push_back(backward);
    }

    void addSymmetric(int u, int v, int cap) {
        Arc* forward = new Arc(u, v, (int)adjacency[v].size(), 0, cap);
        Arc* backward = new Arc(v, u, (int)adjacency[u].size(), 0, cap);
        adjacency[u].push_back(forward);
        adjacency[v].push_back(backward);
    }

    bool buildLevels(int source, int sink) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        q.push(source);
        level[source] = 0;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == sink) return true;
            for (Arc* e : adjacency[u]) {
                if (level[e->terminus] == -1 && e->available() > 0) {
                    level[e->terminus] = level[u] + 1;
                    q.push(e->terminus);
                }
            }
        }
        return false;
    }

    int push(int u, int sink, int flowLimit) {
        if (u == sink) return flowLimit;
        for (int i = 0; i < (int)adjacency[u].size(); ++i) {
            Arc*& e = adjacency[u][i];
            if (level[e->terminus] == level[u] + 1 && e->available() > 0) {
                int pushed = push(e->terminus, sink, min(flowLimit, e->available()));
                if (pushed) {
                    e->current += pushed;
                    adjacency[e->terminus][e->reverse].current -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    long long totalFlow(int src, int snk) {
        long long result = 0;
        while (buildLevels(src, snk)) {
            int pushed;
            while ((pushed = push(src, snk, INT_MAX)) > 0) {
                result += pushed;
            }
        }
        return result;
    }
};

int terrain[MAX_LEN][MAX_LEN], shelterCapacity[MAX_LEN][MAX_LEN], poisonMap[61][MAX_LEN][MAX_LEN];

struct Entity {
    int row, col, quantity;
    Entity(int r, int c, int q) : row(r), col(c), quantity(q) {}
    bool within(int size) const {
        return row >= 0 && row < size && col >= 0 && col < size && terrain[row][col] == CLEAR;
    }
};

bool inBounds(int r, int c, int size) { return Entity(r, c, 0).within(size); }

inline bool operator==(const Entity& a, const Entity& b) {
    return a.row == b.row && a.col == b.col;
}

vector<Entity> people, exits;
const int dRow[4] = {-1, 0, 1, 0};
const int dCol[4] = {0, -1, 0, 1};

int interpret(char c) {
    if (c >= '0' && c <= '9') return CLEAR;
    if (c == 'Y') return REACTION_POINT;
    if (c == 'Z') return DANGER_ZONE;
    return -1;
}

int extractDigit(char c) { return c - '0'; }

int computeDistance(Entity start, Entity end, int size) {
    bitset<MAX_LEN> visited[MAX_LEN];
    queue<pair<int, Entity>> q;
    q.push({0, start});
    visited[start.row][start.col] = true;

    while (!q.empty()) {
        int time = q.front().first;
        Entity cur = q.front().second;
        q.pop();

        if (cur == end) return time;
        if (poisonMap[time][cur.row][cur.col]) continue;

        for (int k = 0; k < 4; ++k) {
            Entity next(cur.row + dRow[k], cur.col + dCol[k], 0);
            if (next.within(size) && !visited[next.row][next.col] && !poisonMap[time][next.row][next.col]) {
                q.push({time + 1, next});
                visited[next.row][next.col] = true;
            }
        }
    }
    return 999;
}

void propagatePoison(int x, int y, int duration, int size) {
    poisonMap[0][x][y] = 1;
    for (int t = 1; t <= duration; ++t) {
        for (int i = 0; i < size; ++i) {
            for (int j = 0; j < size; ++j) {
                if (poisonMap[t-1][i][j]) {
                    poisonMap[t][i][j] = 1;
                    for (int k = 0; k < 4; ++k) {
                        int ni = i + dRow[k], nj = j + dCol[k];
                        if (ni >= 0 && ni < size && nj >= 0 && nj < size && terrain[ni][nj] == CLEAR)
                            poisonMap[t][ni][nj] = 1;
                    }
                }
            }
        }
    }
}

int main() {
    int N, T;
    scanf("%d %d", &N, &T);

    char ch;
    Entity origin{0, 0, 0};
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);
            if (interpret(ch) == CLEAR && extractDigit(ch)) {
                people.emplace_back(i, j, extractDigit(ch));
            }
            terrain[i][j] = interpret(ch);
            if (terrain[i][j] == DANGER_ZONE) origin = Entity(i, j, 0);
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);
            if (interpret(ch) == SHELTER && extractDigit(ch)) {
                exits.emplace_back(i, j, extractDigit(ch));
                shelterCapacity[i][j] = extractDigit(ch);
            }
        }
    }

    FlowEngine* engine = new FlowEngine(MAX_LEN);
    int terminal = MAX_LEN - 1;

    for (size_t i = 0; i < people.size(); ++i)
        engine->addArc(0, i*2 + 1, people[i].quantity);

    for (size_t i = 0; i < exits.size(); ++i)
        engine->addArc(i*2 + 2, terminal, exits[i].quantity);

    propagatePoison(origin.row, origin.col, T, N);

    for (size_t i = 0; i < people.size(); ++i) {
        for (size_t j = 0; j < exits.size(); ++j) {
            int d = computeDistance(people[i], exits[j], N);
            if (d <= T) engine->addArc(i*2 + 1, j*2 + 2, 999);
        }
    }

    printf("%lld\n", engine->totalFlow(0, terminal));
    delete engine;
    return 0;
}
